/// ceiling enforced by <see cref="ShellSizeGuard"/> (24 logic lines, or 100 for
/// the <c>visual-relay</c> bootstrap script). Files are discovered by walking the
/// filesystem (no git subprocess), then classified by the same
/// <see cref="ShellScriptClassifier"/> heuristic the guard uses.
/// </summary>
public sealed class ShellScriptSizeGuardTests
{
    /// <summary>
    /// Gate-as-test: asserts every shell script stays within its size ceiling
    /// (24 logic lines for most scripts, or 100 for the <c>visual-relay</c>
    /// bootstrap). This is the build-failing gate: it fails the moment any shell
    /// script (by extension or hashbang) grows past its ceiling.
    /// </summary>
    [Fact]
    public void AllTrackedShellScripts_AreWithinTheLimit()
    {
        var files = EnumerateProjectScripts(RepoSetup.Root);
        var violations = ShellSizeGuard.FindViolations(files, ShellSizeGuard.ResolveLimit());

        Assert.True(violations.Count == 0,
            "shell-size guard found violations (convert the logic to C#, do not relax the limit):\n" +
            string.Join("\n", violations.Select(v => $"{v.Path}: {v.Count} logic lines (limit {v.Limit})")));
    }

    /// <summary>
    /// Teeth: a tracked 25-line script is reported; a tracked script at
    /// exactly 24 lines passes.
    /// </summary>
    [Fact]
    public void OverLimitScript_IsAViolation_AtLimitScript_IsNot()
    {
        var realFiles = EnumerateProjectScripts(RepoSetup.Root);

        var over = realFiles.Append(("fixtures/too-fat.sh", ShellScript(25))).ToList();
        var overViolations = ShellSizeGuard.FindViolations(over, ShellSizeGuard.ResolveLimit());
        Assert.Contains(overViolations, v => v is { Path: "fixtures/too-fat.sh", Count: 25 });

        var at = realFiles.Append(("fixtures/ok.sh", ShellScript(24))).ToList();
        var atViolations = ShellSizeGuard.FindViolations(at, ShellSizeGuard.ResolveLimit());
        Assert.DoesNotContain(atViolations, v => v.Path == "fixtures/ok.sh");
    }

    /// <summary>
    /// Teeth: a script with exactly 24 logic lines (the ceiling) is NOT
    /// reported.
    /// </summary>
    [Fact]
    public void Teeth_AtLimit_IsNotReported()
    {
        var violation = ShellSizeGuard.CheckScoped("ok.sh", ShellScript(24), ShellSizeGuard.ResolveLimit());
        Assert.Null(violation);
    }

    /// <summary>
    /// Teeth: a script with 25 logic lines IS reported with the correct
    /// path, count, and limit.
    /// </summary>
    [Fact]
    public void Teeth_OneOver_IsReported()
    {
        var violation = ShellSizeGuard.CheckScoped("big.sh", ShellScript(25), ShellSizeGuard.ResolveLimit());
        Assert.NotNull(violation);
        Assert.Equal("big.sh", violation!.Value.Path);
        Assert.Equal(25, violation.Value.Count);
        Assert.Equal(24, violation.Value.Limit);
    }

    /// <summary>
    /// Walks the filesystem at <paramref name="repoRoot"/>, skips the .git
    /// directory, and returns (relativePath, lines) for every file classified
    /// as a shell script by <see cref="ShellScriptClassifier"/>.
    /// </summary>
    private static List<(string Path, string[] Lines)> EnumerateProjectScripts(string repoRoot)
    {
        var results = new List<(string Path, string[] Lines)>();
        foreach (var full in Directory.EnumerateFiles(repoRoot, "*", SearchOption.AllDirectories))
        {
            var rel = Path.GetRelativePath(repoRoot, full);
            // Skip .git internals
            if (IsInsideGitDir(rel))
                continue;
            try
            {
                var firstLine = ReadFirstLine(full);
                if (ShellScriptClassifier.IsShellScript(rel, firstLine))
                {
                    var lines = File.ReadAllLines(full);
                    results.Add((rel, lines));
                }
            }
            catch
            {
                // skip unreadable files
            }
        }
        return results;
    }

    private static bool IsInsideGitDir(string rel) =>
        rel == ".git"
        || rel.StartsWith(".git/", StringComparison.Ordinal)
        || rel.StartsWith(".git" + Path.DirectorySeparatorChar, StringComparison.Ordinal);

    private static string? ReadFirstLine(string path)
    {
        try
        {
            using var reader = new StreamReader(path);
            return reader.ReadLine();
        }
        catch
        {
            return null;
        }
    }

    /// <summary>A hashbanged shell script with <paramref name="logicLines"/> echo lines.</summary>
    private static string[] ShellScript(int logicLines)
    {
        var lines = new List<string> { "#!/usr/bin/env bash" };
        for (var i = 0; i < logicLines; i++)
            lines.Add($"echo line {i + 1}");
        return lines.ToArray();
    }
}

